import{_ as e,o as i,c as r,a2 as a}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"Trait-First Convention","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/traits.md","filePath":"architecture/traits.md","lastUpdated":1780254295000}'),n={name:"architecture/traits.md"};function o(s,t,l,c,d,p){return i(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="trait-first-convention" tabindex="-1">Trait-First Convention <a class="header-anchor" href="#trait-first-convention" aria-label="Permalink to &quot;Trait-First Convention&quot;">​</a></h1><p>This repo now prefers <strong>traits as the default abstraction</strong>. Patterns to follow:</p><ul><li><strong>Behavior lives behind traits.</strong> Define a trait in the owning crate (e.g., peer, HTTP, IPC) and implement it per binary or adapter. Avoid scattered helper functions.</li><li><strong>Small structs or newtypes implement traits.</strong> Keep logic attached to concrete types instead of “free-floating” functions. Use free functions only for pure, stateless utilities.</li><li><strong>Default methods over helper modules.</strong> Put common runners/wrappers as default trait methods when possible (e.g., <code>run()</code> on a service trait).</li><li><strong>Ownership lives where the capability belongs.</strong> Define the trait near the core capability (peer, storage, HTTP, IPC), then implement it in consumers (bins/adapters).</li><li><strong>Testing via contracts.</strong> Unit tests should target trait contracts, using lightweight mock implementations to validate behavior.</li><li><strong>Binaries stay thin.</strong> Bins should compose trait implementations and call <code>run()</code>, not host business logic.</li></ul><p>Examples to apply next:</p><ul><li>Peer identity/spawn: trait in <code>soma-peer</code>, implemented by the daemon library and by each <code>somad</code> subcommand that runs a peer (<code>bot</code>, etc.).</li><li>HTTP services: trait in <code>soma-core</code> (or service crate), implemented per <code>somad</code> subcommand.</li></ul><p>Keep traits cohesive, name methods for intent, and avoid leaking unrelated concerns into a single trait.</p>',6)])])}const u=e(n,[["render",o]]);export{h as __pageData,u as default};
